    "import { useState, useRef } from \"react\";\nimport {\n  Box,\n  TextField,\n  Typography,\n  Button,\n  Stack,\n  Alert,\n  Input,\n} from \"@mui/material\";\nimport { parseFile } from \"../utils/fileParsers\";\n\ninterface TextInputScreenProps {\n  text: string;\n  onTextChange: (text: string) => void;\n}\n\nexport function TextInputScreen({ text, onTextChange }: TextInputScreenProps) {\n  const [url, setUrl] = useState(\"\");\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  const handleLoadFromUrl = async () => {\n    if (!url.trim()) {\n      setError(\"Please enter a URL\");\n      return;\n    }\n\n    setLoading(true);\n    setError(null);\n\n    try {\n      const response = await fetch(url);\n      if (!response.ok) {\n        throw new Error(`Failed to load: ${response.statusText}`);\n      }\n      const content = await response.text();\n      onTextChange(content);\n      setUrl(\"\");\n    } catch (err) {\n      setError(err instanceof Error ? err.message : \"Failed to load from URL\");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  const handleFileSelect = async (event: React.ChangeEvent<HTMLInputElement>) => {\n    const file = event.target.files?.[0];\n    if (!file) return;\n\n    setLoading(true);\n    setError(null);\n\n    try {\n      const content = await parseFile(file);\n      onTextChange(content);\n    } catch (err) {\n      setError(err instanceof Error ? err.message : \"Failed to parse file\");\n    } finally {\n      setLoading(false);\n      if (fileInputRef.current) {\n        fileInputRef.current.value = \"\";\n      }\n    }\n  };\n\n  const handleFileButtonClick = () => {\n    fileInputRef.current?.click();\n  };\n\n  return (\n    <Box sx={{ p: 3, height: \"100%\", display: \"flex\", flexDirection: \"column\" }}>\n      <Typography variant=\"h5\" gutterBottom>\n        Text Input\n      </Typography>\n\n      <Stack spacing={2} sx={{ mt: 2 }}>\n        <Stack direction=\"row\" spacing={2} alignItems=\"center\">\n          <TextField\n            label=\"Load from URL\"\n            value={url}\n            onChange={(e) => setUrl(e.target.value)}\n            placeholder=\"https://example.com/text.txt\"\n            fullWidth\n            size=\"small\"\n            onKeyDown={(e) => {\n              if (e.key === \"Enter\" && !e.shiftKey) {\n                e.preventDefault();\n                handleLoadFromUrl();\n              }\n            }}\n          />\n          <Button\n            variant=\"contained\"\n            onClick={handleLoadFromUrl}\n            disabled={loading}\n            sx={{ minWidth: 100 }}\n          >\n            Load\n          </Button>\n        </Stack>\n\n        <Button\n          variant=\"outlined\"\n          onClick={handleFileButtonClick}\n          disabled={loading}\n          fullWidth\n        >\n          Load from File (TXT, HTML, EPUB, FB2)\n        </Button>\n\n        <Input\n          type=\"file\"\n          inputRef={fileInputRef}\n          onChange={handleFileSelect}\n          accept=\".txt,.html,.htm,.epub,.fb2\"\n          sx={{ display: \"none\" }}\n        />\n\n        {error && (\n          <Alert severity=\"error\" onClose={() => setError(null)}>\n            {error}\n          </Alert>\n        )}\n      </Stack>\n\n      <TextField\n        multiline\n        rows={20}\n        fullWidth\n        value={text}\n        onChange={(e) => onTextChange(e.target.value)}\n        placeholder=\"Paste your Mandarin text here...\"\n        sx={{ flexGrow: 1, mt: 2 }}\n        disabled={loading}\n      />\n    </Box>\n  );\n}\n\n",
    "import JSZip from \"jszip\";\n\nexport async function parseTextFile(file: File): Promise<string> {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader();\n    reader.onload = (e) => {\n      const text = e.target?.result as string;\n      resolve(text);\n    };\n    reader.onerror = () => reject(new Error(\"Failed to read file\"));\n    reader.readAsText(file, \"UTF-8\");\n  });\n}\n\nexport async function parseHtmlFile(file: File): Promise<string> {\n  const htmlContent = await parseTextFile(file);\n  const parser = new DOMParser();\n  const doc = parser.parseFromString(htmlContent, \"text/html\");\n  \n  const body = doc.body;\n  if (!body) return htmlContent;\n  \n  return body.textContent || body.innerText || \"\";\n}\n\nexport async function parseEpubFile(file: File): Promise<string> {\n  const arrayBuffer = await file.arrayBuffer();\n  const zip = await JSZip.loadAsync(arrayBuffer);\n  \n  const containerXml = await zip.file(\"META-INF/container.xml\")?.async(\"string\");\n  if (!containerXml) {\n    throw new Error(\"Invalid EPUB: container.xml not found\");\n  }\n  \n  const parser = new DOMParser();\n  const containerDoc = parser.parseFromString(containerXml, \"text/xml\");\n  const rootfileElement = containerDoc.querySelector(\"rootfile[media-type='application/oebps-package+xml']\");\n  const opfPath = rootfileElement?.getAttribute(\"full-path\");\n  \n  if (!opfPath) {\n    throw new Error(\"Invalid EPUB: OPF file not found\");\n  }\n  \n  const opfContent = await zip.file(opfPath)?.async(\"string\");\n  if (!opfContent) {\n    throw new Error(\"Invalid EPUB: OPF file could not be read\");\n  }\n  \n  const opfDoc = parser.parseFromString(opfContent, \"text/xml\");\n  const manifestItems = opfDoc.querySelectorAll(\"manifest > item[media-type='application/xhtml+xml'], manifest > item[media-type='text/html']\");\n  \n  const basePath = opfPath.substring(0, opfPath.lastIndexOf(\"/\") + 1);\n  const textParts: string[] = [];\n  \n  for (const item of Array.from(manifestItems)) {\n    const href = item.getAttribute(\"href\");\n    if (!href) continue;\n    \n    const fullPath = basePath + href;\n    const htmlContent = await zip.file(fullPath)?.async(\"string\");\n    if (htmlContent) {\n      const htmlDoc = parser.parseFromString(htmlContent, \"text/html\");\n      const body = htmlDoc.body;\n      if (body) {\n        const text = body.textContent || body.innerText || \"\";\n        textParts.push(text);\n      }\n    }\n  }\n  \n  return textParts.join(\"\\n\\n\");\n}\n\nexport async function parseFb2File(file: File): Promise<string> {\n  const xmlContent = await parseTextFile(file);\n  const parser = new DOMParser();\n  const doc = parser.parseFromString(xmlContent, \"text/xml\");\n  \n  const body = doc.querySelector(\"body\");\n  if (!body) {\n    return \"\";\n  }\n  \n  const sections = body.querySelectorAll(\"section\");\n  const textParts: string[] = [];\n  \n  sections.forEach((section) => {\n    const paragraphs = section.querySelectorAll(\"p\");\n    paragraphs.forEach((p) => {\n      const text = p.textContent || \"\";\n      if (text.trim()) {\n        textParts.push(text.trim());\n      }\n    });\n  });\n  \n  if (textParts.length === 0) {\n    const paragraphs = body.querySelectorAll(\"p\");\n    paragraphs.forEach((p) => {\n      const text = p.textContent || \"\";\n      if (text.trim()) {\n        textParts.push(text.trim());\n      }\n    });\n  }\n  \n  return textParts.join(\"\\n\\n\");\n}\n\nexport async function parseFile(file: File): Promise<string> {\n  const extension = file.name.split(\".\").pop()?.toLowerCase();\n  \n  switch (extension) {\n    case \"txt\":\n      return parseTextFile(file);\n    case \"html\":\n    case \"htm\":\n      return parseHtmlFile(file);\n    case \"epub\":\n      return parseEpubFile(file);\n    case \"fb2\":\n      return parseFb2File(file);\n    default:\n      throw new Error(`Unsupported file type: ${extension}`);\n  }\n}\n\n",
    "import { useState, useEffect, useMemo } from \"react\";\nimport {\n  Box,\n  Typography,\n  Table,\n  TableBody,\n  TableCell,\n  TableContainer,\n  TableHead,\n  TableRow,\n  Paper,\n  Switch,\n  FormControlLabel,\n  Stack,\n} from \"@mui/material\";\nimport { HanziListStore } from \"../store/HanziListStore\";\nimport { PREDEFINED_LISTS } from \"../store/predefinedLists\";\nimport { HanziList } from \"../store/types/HanziList\";\n\ninterface ReportScreenProps {\n  text: string;\n}\n\ninterface ListStats {\n  list: HanziList;\n  count: number;\n  percentage: number;\n}\n\nexport function ReportScreen({ text }: ReportScreenProps) {\n  const [store] = useState(() => new HanziListStore());\n  const [userLists, setUserLists] = useState<HanziList[]>([]);\n  const [enabledLists, setEnabledLists] = useState<Set<string>>(new Set());\n\n  useEffect(() => {\n    const lists = store.load();\n    setUserLists(lists);\n    // Enable all lists by default\n    const allListNames = [\n      ...PREDEFINED_LISTS.map((l) => l.name),\n      ...lists.map((l) => l.name),\n    ];\n    setEnabledLists(new Set(allListNames));\n  }, []);\n\n  const allLists = useMemo(() => {\n    return [...PREDEFINED_LISTS, ...userLists];\n  }, [userLists]);\n\n  const handleToggleList = (listName: string) => {\n    setEnabledLists((prev) => {\n      const next = new Set(prev);\n      if (next.has(listName)) {\n        next.delete(listName);\n      } else {\n        next.add(listName);\n      }\n      return next;\n    });\n  };\n\n  const stats = useMemo(() => {\n    if (!text) return [];\n\n    const textHanzi = Array.from(text).filter((char) =>\n      /[\\u4e00-\\u9fff]/.test(char)\n    );\n    const totalHanzi = textHanzi.length;\n    if (totalHanzi === 0) return [];\n\n    const enabledListsData = allLists.filter((list) =>\n      enabledLists.has(list.name)\n    );\n\n    const listStats: ListStats[] = enabledListsData.map((list) => {\n      const listHanziSet = new Set(Array.from(list.data));\n      const count = textHanzi.filter((char) => listHanziSet.has(char)).length;\n      const percentage = totalHanzi > 0 ? (count / totalHanzi) * 100 : 0;\n      return { list, count, percentage };\n    });\n\n    // Calculate \"not in any list\" hanzi\n    const allListHanziSet = new Set<string>();\n    enabledListsData.forEach((list) => {\n      Array.from(list.data).forEach((char) => allListHanziSet.add(char));\n    });\n\n    const notInAnyList = textHanzi.filter(\n      (char) => !allListHanziSet.has(char)\n    );\n    const notInAnyListCount = notInAnyList.length;\n    const notInAnyListPercentage =\n      totalHanzi > 0 ? (notInAnyListCount / totalHanzi) * 100 : 0;\n\n    return { listStats, notInAnyListCount, notInAnyListPercentage, totalHanzi };\n  }, [text, allLists, enabledLists]);\n\n  return (\n    <Box sx={{ p: 3, height: \"100%\", display: \"flex\", flexDirection: \"column\" }}>\n      <Typography variant=\"h5\" gutterBottom>\n        Report\n      </Typography>\n\n      <Box sx={{ mt: 3, mb: 3 }}>\n        <Typography variant=\"h6\" gutterBottom>\n          Lists\n        </Typography>\n        <Stack spacing={1}>\n          {allLists.map((list) => (\n            <FormControlLabel\n              key={list.name}\n              control={\n                <Switch\n                  checked={enabledLists.has(list.name)}\n                  onChange={() => handleToggleList(list.name)}\n                />\n              }\n              label={`${list.name} (${list.type})`}\n            />\n          ))}\n        </Stack>\n      </Box>\n\n      {text && stats && \"listStats\" in stats && (\n        <Box sx={{ flexGrow: 1, overflow: \"auto\" }}>\n          <Typography variant=\"h6\" gutterBottom>\n            Statistics\n          </Typography>\n          <TableContainer component={Paper}>\n            <Table>\n              <TableHead>\n                <TableRow>\n                  <TableCell>List</TableCell>\n                  <TableCell align=\"right\">Count</TableCell>\n                  <TableCell align=\"right\">Percentage</TableCell>\n                </TableRow>\n              </TableHead>\n              <TableBody>\n                {stats.listStats.map((stat) => (\n                  <TableRow key={stat.list.name}>\n                    <TableCell>{stat.list.name}</TableCell>\n                    <TableCell align=\"right\">{stat.count}</TableCell>\n                    <TableCell align=\"right\">\n                      {stat.percentage.toFixed(2)}%\n                    </TableCell>\n                  </TableRow>\n                ))}\n                <TableRow>\n                  <TableCell>\n                    <strong>Not in any list</strong>\n                  </TableCell>\n                  <TableCell align=\"right\">\n                    <strong>{stats.notInAnyListCount}</strong>\n                  </TableCell>\n                  <TableCell align=\"right\">\n                    <strong>{stats.notInAnyListPercentage.toFixed(2)}%</strong>\n                  </TableCell>\n                </TableRow>\n                <TableRow>\n                  <TableCell>\n                    <strong>Total</strong>\n                  </TableCell>\n                  <TableCell align=\"right\">\n                    <strong>{stats.totalHanzi}</strong>\n                  </TableCell>\n                  <TableCell align=\"right\">\n                    <strong>100.00%</strong>\n                  </TableCell>\n                </TableRow>\n              </TableBody>\n            </Table>\n          </TableContainer>\n        </Box>\n      )}\n\n      {!text && (\n        <Typography variant=\"body2\" sx={{ mt: 2, color: \"text.secondary\" }}>\n          Enter text in the Text Input screen to see the report.\n        </Typography>\n      )}\n    </Box>\n  );\n}\n",
    "import { HanziList } from \"./types/HanziList\";\n\nconst STORAGE_KEY = \"hanzi_lists\";\n\nexport class HanziListStore {\n  private lists: HanziList[] = [];\n\n  load(): HanziList[] {\n    try {\n      const stored = localStorage.getItem(STORAGE_KEY);\n      if (stored) {\n        this.lists = JSON.parse(stored);\n      } else {\n        this.lists = [];\n      }\n      return [...this.lists];\n    } catch (error) {\n      console.error(\"Failed to load hanzi lists from localStorage:\", error);\n      this.lists = [];\n      return [];\n    }\n  }\n\n  save(lists: HanziList[]): void {\n    try {\n      this.lists = [...lists];\n      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.lists));\n    } catch (error) {\n      console.error(\"Failed to save hanzi lists to localStorage:\", error);\n      throw error;\n    }\n  }\n\n  getLists(): HanziList[] {\n    return [...this.lists];\n  }\n}\n\n",
    "import { HanziList, HanziListType } from \"./types/HanziList\";\n\nexport const PREDEFINED_LISTS: HanziList[] = [\n  {\n    name: \"Old HSK 1\",\n    type: HanziListType.Inclusive,\n    data: \"的一是不了在人有我他这个们中来上大和国说时出会你对生能子那下年后作里家多么去学都同现没面起看天分好小些样她本前开想机十工明三关点高很见什二果西月话回老先儿东水名几认系气打女四电少太再做期五书听住北觉师今院识候飞车服怎呢叫影字爱商请视九写八吗吃六医号语七兴星京米客友钱热坐校脑谁哪喜习欢冷汉衣妈读买岁块姐亮朋谢钟雨饭睡喝午店爸桌菜茶狗杯租昨漂椅猫喂苹\",\n    color: \"#fce4ec\",\n  },\n  {\n    name: \"Old HSK 2\",\n    type: HanziListType.Inclusive,\n    data: \"为到以要就可也得着过道所然事经动还进但因从日意它长第公已情知正外两间问最手体等新身表给次门常教比员真走条题别报务场件便司眼非白思完色路告边望共让运笑步每快往近夫准始远备百离病息火早找吧考红虽希房黑足孩站诉千男助乐球错晚试送药游室您帮左右穿哥弟慢忙介鱼跑贵班票睛旅笔卖旁阴跳雪肉馆牛纸歌床玩妻休舞姓妹汽课懂绍丈洗唱奶宜累羊零蛋鸡宾颜瓜晴啡篮咖踢泳铅\",\n    color: \"#f8bbd0\",\n  },\n  {\n    name: \"Old HSK 3\",\n    type: HanziListType.Inclusive,\n    data: \"饱城哭物根口瓶元环片主风束练跟响史居惯育历特料变相鞋心向自胖极春复空爬夏重南糕被静香急帽啤阳骑图注锻除境害李马干清假蓝平信单易盘需只越简舒世黄总顾加朵阿当伞张山半季乎搬园嘴腿护换赛净接万选力鼻渴用突音发级或该辆难久而法参灯择瘦银楼于鸟迎闻饿业牙理婚像蕉查己文词较鲜聪安段扫怕邻铁筷炼又冬满奇目碗须附化头典把努愿爷办船故担轻梯短甜疼秋数树板迟定楚旧句界答行姨熊借照容遇如周刮裤斤绿且种脚画讲地者坏决河裙求草提终趣末成放层冒才酒耳市矮皮必记更方拿留烧算角衫带直据包差般刚邮冰啊叔戏健康感声节衬街箱绩花礼卡议应双超忘刷位其澡实怪脸结网调刻饮聊检解\",\n    color: \"#f48fb1\",\n  },\n  {\n    name: \"Old HSK 4\",\n    type: HanziListType.Inclusive,\n    data: \"划专亚倒普永咳鸭象忆按反疑紧深袋麻众傅膊幽济拒幸确赚否示厕养戴联续巾帅扰绝猜硕申论技此圾导闹肥章辛植验够购染骄童漫支怜部美则处海厉连恼术士悔细察排即误性勺材聚弹之油克禁售指案袜止羞堵乓微乒富纪航态利慕功消尽艺温规勇围输概扮符嗽户命减占获寄拜虑内暑膏谈允降虎距匙谅寒资激死呼肚估彩励台译效盒竞趟速牌棵失散泉林律原辣默粗醒讨江各缺具祝熟遍付梦言亲松抬偶柿值迷整剩址咸首负母伙使改顺码优及敲封洲翻证陪厨叶断计汁详丽郊研尊况傲弄笨传云精洋广凉戚巧究格躺烤篇管怀敢许扔困密钥盐惜举批入增惊苦悉保底愉弃沙葡款泼合逛全随肯鼓座列歉厅压掉尝基饼脱局低龄诚萄羽汗暖质脾挂式肤拾础活推标争至耐供汤剧存印页挺奖任刀份镜险餐停谊俩将貌棒适引危货收费扬签际恐评父穷针卫倍建稍抽却交懒邀羡序赢受味浪破免光毛严并塑擦播呀杂著糖败授脏展登仔福拉琴暂互另度吸何甚流释秒饺科持胳判乘阅无例矿桥修既孙钢烟价污填坚队职责厌预区籍秀志仅社毕景取转积线酸尤奋约赶族与通丰乱演由咱金伤竟尔聘丢折烦桶警落森程省垃继贺仍量抱民键窗招切厚橡博骗观\",\n    color: \"#f06292\",\n  },\n  {\n    name: \"Old HSK 5\",\n    type: HanziListType.Inclusive,\n    data: \"龙返玉吨控删秩呆闭谨委幅庭浇撕革尘震描豆吻蝴纲兄未匆诊托待守匀范碍惭慎挤夜威趋宠谓采食坦盖斗嚏均鼠洒似代荣念歪糟器齿捡英岛营置喊财项充咨窄创弱洞蔬彼逃阶胡嫁筑催柜组挥哈迅顿临夹孕殊躲愁核粘夸嘉婆录显询阻域宣屋欣淘尾惠补届朗赔墙迫召抄皂烈矩靠税跃棋恨装恳武灵滩享娱眠犹枪蛇绕布刺农粮射称施抖频歇肌毒疯延偷沉赏测防熬繁扩配宽姿堆余宿吹巨固氛亏宁壁致悠尚雄糊佛宴帘碰依硬润妨群综扇椒势兔耽梨宝恋紫挑币晒织匹避古遵某毯吓恢设甲形傍盾薄恭型挡眉藏劳锁册伸狮甩疲谦彻欧虚酱妙唯艳血曾烂青池投振顶掌土骨泛桃胁府劣透忽军华毫良略木卧骤逐驾诗霉蜂屈睁纯圈炮兑拥治培盆达纷伟