    "import { useState, useEffect, useMemo } from \"react\";\nimport {\n  Box,\n  Typography,\n  Fab,\n  Dialog,\n  DialogTitle,\n  DialogContent,\n  DialogActions,\n  Button,\n  TextField,\n  Select,\n  MenuItem,\n  FormControl,\n  InputLabel,\n  Paper,\n  List,\n  ListItem,\n  ListItemText,\n  Divider,\n  IconButton,\n  ListItemSecondaryAction,\n  Chip,\n  Collapse,\n} from \"@mui/material\";\nimport { ExpandMore, ExpandLess } from \"@mui/icons-material\";\nimport { Add, Delete, Edit, ContentCopy } from \"@mui/icons-material\";\nimport { HanziList, HanziListType } from \"../store/types/HanziList\";\nimport { HanziListStore } from \"../store/HanziListStore\";\nimport { PREDEFINED_LISTS } from \"../store/predefinedLists\";\n\nexport function ConfigurationScreen() {\n  const [open, setOpen] = useState(false);\n  const [editingIndex, setEditingIndex] = useState<number | null>(null);\n  const [newListName, setNewListName] = useState(\"\");\n  const [newListType, setNewListType] = useState<HanziListType>(\n    HanziListType.Inclusive\n  );\n  const [newListData, setNewListData] = useState(\"\");\n  const [newListColor, setNewListColor] = useState(\"#1976d2\");\n  const [userLists, setUserLists] = useState<HanziList[]>([]);\n  const [expandedLists, setExpandedLists] = useState<Set<string>>(new Set());\n  const store = useMemo(() => new HanziListStore(), []);\n\n  useEffect(() => {\n    try {\n      const lists = store.load();\n      setUserLists(lists);\n    } catch (error) {\n      console.error(\"Failed to load lists:\", error);\n      setUserLists([]);\n    }\n  }, [store]);\n\n  const handleOpen = () => {\n    setEditingIndex(null);\n    setNewListName(\"\");\n    setNewListType(HanziListType.Inclusive);\n    setNewListData(\"\");\n    setNewListColor(\"#1976d2\");\n    setOpen(true);\n  };\n\n  const handleEdit = (list: HanziList) => {\n    const globalIndex = userLists.findIndex(\n      (l) => l.name === list.name && l.type === list.type\n    );\n    if (globalIndex !== -1) {\n      setEditingIndex(globalIndex);\n      setNewListName(list.name);\n      setNewListType(list.type);\n      setNewListData(list.data);\n      setNewListColor(list.color || \"#1976d2\");\n      setOpen(true);\n    }\n  };\n\n  const handleDelete = (list: HanziList) => {\n    const updatedLists = userLists.filter(\n      (l) => !(l.name === list.name && l.type === list.type)\n    );\n    store.save(updatedLists);\n    setUserLists(updatedLists);\n  };\n\n  const handleCopy = async (list: HanziList) => {\n    try {\n      await navigator.clipboard.writeText(list.data);\n    } catch (error) {\n      console.error(\"Failed to copy to clipboard:\", error);\n    }\n  };\n\n  const handleClose = () => {\n    setOpen(false);\n    setEditingIndex(null);\n    setNewListName(\"\");\n    setNewListType(HanziListType.Inclusive);\n    setNewListData(\"\");\n    setNewListColor(\"#1976d2\");\n  };\n\n  const handleSave = () => {\n    if (!newListName.trim() || !newListData.trim()) {\n      return;\n    }\n\n    const updatedList: HanziList = {\n      name: newListName.trim(),\n      type: newListType,\n      data: newListData.trim(),\n      color: newListColor,\n    };\n\n    let updatedLists: HanziList[];\n    if (editingIndex !== null) {\n      updatedLists = [...userLists];\n      updatedLists[editingIndex] = updatedList;\n    } else {\n      updatedLists = [...userLists, updatedList];\n    }\n\n    store.save(updatedLists);\n    setUserLists(updatedLists);\n    handleClose();\n  };\n\n  const toggleListExpansion = (listKey: string) => {\n    const newExpanded = new Set(expandedLists);\n    if (newExpanded.has(listKey)) {\n      newExpanded.delete(listKey);\n    } else {\n      newExpanded.add(listKey);\n    }\n    setExpandedLists(newExpanded);\n  };\n\n  const getListKey = (list: HanziList, index: number) => {\n    return `${list.name}-${list.type}-${index}`;\n  };\n\n  const inclusiveLists = userLists.filter(\n    (list) => list.type === HanziListType.Inclusive\n  );\n  const exclusiveLists = userLists.filter(\n    (list) => list.type === HanziListType.Exclusive\n  );\n\n  return (\n    <Box sx={{ p: 3, height: \"100%\", pb: 10, position: \"relative\" }}>\n      <Typography variant=\"h5\" gutterBottom>\n        Configuration\n      </Typography>\n\n      <Box sx={{ mt: 3 }}>\n        <Typography variant=\"h6\" gutterBottom>\n          Pre-defined Lists\n        </Typography>\n        <Paper variant=\"outlined\" sx={{ mb: 3 }}>\n          <List>\n            {PREDEFINED_LISTS.map((list, index) => {\n              const listKey = `predefined-${index}`;\n              const isExpanded = expandedLists.has(listKey);\n              return (\n                <div key={index}>\n                  <ListItem>\n                    {list.color && (\n                      <Box\n                        sx={{\n                          width: 16,\n                          height: 16,\n                          borderRadius: \"50%\",\n                          backgroundColor: list.color,\n                          mr: 1,\n                          border: \"1px solid\",\n                          borderColor: \"divider\",\n                        }}\n                        aria-label={`Color: ${list.color}`}\n                      />\n                    )}\n                    <ListItemText\n                      primary={list.name}\n                      secondary={`Type: ${list.type} | Characters: ${list.data.length}`}\n                    />\n                    <ListItemSecondaryAction>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label={isExpanded ? \"collapse\" : \"expand\"}\n                        onClick={() => toggleListExpansion(listKey)}\n                        sx={{ mr: 1 }}\n                      >\n                        {isExpanded ? <ExpandLess /> : <ExpandMore />}\n                      </IconButton>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label=\"copy\"\n                        onClick={() => handleCopy(list)}\n                      >\n                        <ContentCopy />\n                      </IconButton>\n                    </ListItemSecondaryAction>\n                  </ListItem>\n                  <Collapse in={isExpanded} timeout=\"auto\" unmountOnExit>\n                    <Box sx={{ p: 2, pt: 0 }}>\n                      <Typography variant=\"caption\" color=\"text.secondary\" sx={{ mb: 1, display: \"block\" }}>\n                        All characters in this list:\n                      </Typography>\n                      <Box\n                        sx={{\n                          display: \"flex\",\n                          flexWrap: \"wrap\",\n                          gap: 0.5,\n                          maxHeight: \"300px\",\n                          overflowY: \"auto\",\n                        }}\n                        role=\"list\"\n                        aria-label={`Characters in ${list.name}`}\n                      >\n                        {Array.from(list.data).map((char, charIndex) => (\n                          <Chip\n                            key={`${listKey}-char-${charIndex}`}\n                            label={char}\n                            size=\"small\"\n                            sx={{\n                              backgroundColor: list.color\n                                ? `${list.color}20`\n                                : \"action.selected\",\n                              border: `1px solid ${list.color || \"#1976d2\"}`,\n                              fontSize: \"1.2rem\",\n                              minWidth: \"2.5rem\",\n                              height: \"2.5rem\",\n                            }}\n                            aria-label={`Character: ${char}`}\n                          />\n                        ))}\n                      </Box>\n                    </Box>\n                  </Collapse>\n                  {index < PREDEFINED_LISTS.length - 1 && <Divider />}\n                </div>\n              );\n            })}\n          </List>\n        </Paper>\n\n        <Typography variant=\"h6\" gutterBottom>\n          Inclusive Lists\n        </Typography>\n        <Paper variant=\"outlined\" sx={{ mb: 3 }}>\n          {inclusiveLists.length === 0 ? (\n            <Box sx={{ p: 2, textAlign: \"center\", color: \"text.secondary\" }}>\n              No inclusive lists yet\n            </Box>\n          ) : (\n            <List>\n              {inclusiveLists.map((list, index) => {\n              const listKey = getListKey(list, index);\n              const isExpanded = expandedLists.has(listKey);\n              return (\n                <div key={listKey}>\n                  <ListItem>\n                    <Box\n                      sx={{\n                        width: 16,\n                        height: 16,\n                        borderRadius: \"50%\",\n                        backgroundColor: list.color || \"#1976d2\",\n                        mr: 1,\n                        border: \"1px solid\",\n                        borderColor: \"divider\",\n                      }}\n                      aria-label={`Color: ${list.color || \"#1976d2\"}`}\n                    />\n                    <ListItemText\n                      primary={list.name}\n                      secondary={`Characters: ${list.data.length}`}\n                    />\n                    <ListItemSecondaryAction>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label={isExpanded ? \"collapse\" : \"expand\"}\n                        onClick={() => toggleListExpansion(listKey)}\n                        sx={{ mr: 1 }}\n                      >\n                        {isExpanded ? <ExpandLess /> : <ExpandMore />}\n                      </IconButton>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label=\"copy\"\n                        onClick={() => handleCopy(list)}\n                        sx={{ mr: 1 }}\n                      >\n                        <ContentCopy />\n                      </IconButton>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label=\"edit\"\n                        onClick={() => handleEdit(list)}\n                        sx={{ mr: 1 }}\n                      >\n                        <Edit />\n                      </IconButton>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label=\"delete\"\n                        onClick={() => handleDelete(list)}\n                        color=\"error\"\n                      >\n                        <Delete />\n                      </IconButton>\n                    </ListItemSecondaryAction>\n                  </ListItem>\n                  <Collapse in={isExpanded} timeout=\"auto\" unmountOnExit>\n                    <Box sx={{ p: 2, pt: 0 }}>\n                      <Typography variant=\"caption\" color=\"text.secondary\" sx={{ mb: 1, display: \"block\" }}>\n                        All characters in this list:\n                      </Typography>\n                      <Box\n                        sx={{\n                          display: \"flex\",\n                          flexWrap: \"wrap\",\n                          gap: 0.5,\n                          maxHeight: \"300px\",\n                          overflowY: \"auto\",\n                        }}\n                        role=\"list\"\n                        aria-label={`Characters in ${list.name}`}\n                      >\n                        {Array.from(list.data).map((char, charIndex) => (\n                          <Chip\n                            key={`${listKey}-char-${charIndex}`}\n                            label={char}\n                            size=\"small\"\n                            sx={{\n                              backgroundColor: list.color\n                                ? `${list.color}20`\n                                : \"action.selected\",\n                              border: `1px solid ${list.color || \"#1976d2\"}`,\n                              fontSize: \"1.2rem\",\n                              minWidth: \"2.5rem\",\n                              height: \"2.5rem\",\n                            }}\n                            aria-label={`Character: ${char}`}\n                          />\n                        ))}\n                      </Box>\n                    </Box>\n                  </Collapse>\n                  {index < inclusiveLists.length - 1 && <Divider />}\n                </div>\n              );\n            })}\n            </List>\n          )}\n        </Paper>\n\n        <Typography variant=\"h6\" gutterBottom>\n          Exclusive Lists\n        </Typography>\n        <Paper variant=\"outlined\" sx={{ mb: 3 }}>\n          {exclusiveLists.length === 0 ? (\n            <Box sx={{ p: 2, textAlign: \"center\", color: \"text.secondary\" }}>\n              No exclusive lists yet\n            </Box>\n          ) : (\n            <List>\n              {exclusiveLists.map((list, index) => {\n              const listKey = getListKey(list, index);\n              const isExpanded = expandedLists.has(listKey);\n              return (\n                <div key={listKey}>\n                  <ListItem>\n                    <Box\n                      sx={{\n                        width: 16,\n                        height: 16,\n                        borderRadius: \"50%\",\n                        backgroundColor: list.color || \"#1976d2\",\n                        mr: 1,\n                        border: \"1px solid\",\n                        borderColor: \"divider\",\n                      }}\n                      aria-label={`Color: ${list.color || \"#1976d2\"}`}\n                    />\n                    <ListItemText\n                      primary={list.name}\n                      secondary={`Characters: ${list.data.length}`}\n                    />\n                    <ListItemSecondaryAction>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label={isExpanded ? \"collapse\" : \"expand\"}\n                        onClick={() => toggleListExpansion(listKey)}\n                        sx={{ mr: 1 }}\n                      >\n                        {isExpanded ? <ExpandLess /> : <ExpandMore />}\n                      </IconButton>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label=\"copy\"\n                        onClick={() => handleCopy(list)}\n                        sx={{ mr: 1 }}\n                      >\n                        <ContentCopy />\n                      </IconButton>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label=\"edit\"\n                        onClick={() => handleEdit(list)}\n                        sx={{ mr: 1 }}\n                      >\n                        <Edit />\n                      </IconButton>\n                      <IconButton\n                        edge=\"end\"\n                        aria-label=\"delete\"\n                        onClick={() => handleDelete(list)}\n                        color=\"error\"\n                      >\n                        <Delete />\n                      </IconButton>\n                    </ListItemSecondaryAction>\n                  </ListItem>\n                  <Collapse in={isExpanded} timeout=\"auto\" unmountOnExit>\n                    <Box sx={{ p: 2, pt: 0 }}>\n                      <Typography variant=\"caption\" color=\"text.secondary\" sx={{ mb: 1, display: \"block\" }}>\n                        All characters in this list:\n                      </Typography>\n                      <Box\n                        sx={{\n                          display: \"flex\",\n                          flexWrap: \"wrap\",\n                          gap: 0.5,\n                          maxHeight: \"300px\",\n                          overflowY: \"auto\",\n                        }}\n                        role=\"list\"\n                        aria-label={`Characters in ${list.name}`}\n                      >\n                        {Array.from(list.data).map((char, charIndex) => (\n                          <Chip\n                            key={`${listKey}-char-${charIndex}`}\n                            label={char}\n                            size=\"small\"\n                            sx={{\n                              backgroundColor: list.color\n                                ? `${list.color}20`\n                                : \"action.selected\",\n                              border: `1px solid ${list.color || \"#1976d2\"}`,\n                              fontSize: \"1.2rem\",\n                              minWidth: \"2.5rem\",\n                              height: \"2.5rem\",\n                            }}\n                            aria-label={`Character: ${char}`}\n                          />\n                        ))}\n                      </Box>\n                    </Box>\n                  </Collapse>\n                  {index < exclusiveLists.length - 1 && <Divider />}\n                </div>\n              );\n            })}\n            </List>\n          )}\n        </Paper>\n      </Box>\n\n      <Fab\n        color=\"primary\"\n        aria-label=\"add\"\n        sx={{ position: \"fixed\", bottom: 80, right: 16 }}\n        onClick={handleOpen}\n      >\n        <Add />\n      </Fab>\n\n      <Dialog open={open} onClose={handleClose} maxWidth=\"sm\" fullWidth>\n        <DialogTitle>\n          {editingIndex !== null ? \"Edit List\" : \"Create New List\"}\n        </DialogTitle>\n        <DialogContent>\n          <Box sx={{ display: \"flex\", flexDirection: \"column\", gap: 2, mt: 1 }}>\n            <TextField\n              label=\"List Name\"\n              fullWidth\n              value={newListName}\n              onChange={(e) => setNewListName(e.target.value)}\n              required\n            />\n            <FormControl fullWidth>\n              <InputLabel>Type</InputLabel>\n              <Select\n                value={newListType}\n                label=\"Type\"\n                onChange={(e) => setNewListType(e.target.value as HanziListType)}\n              >\n                <MenuItem value={HanziListType.Inclusive}>Inclusive</MenuItem>\n                <MenuItem value={HanziListType.Exclusive}>Exclusive</MenuItem>\n              </Select>\n            </FormControl>\n            <TextField\n              label=\"Hanzi Characters\"\n              fullWidth\n              multiline\n              rows={4}\n              value={newListData}\n              onChange={(e) => setNewListData(e.target.value)}\n              placeholder=\"Enter hanzi characters...\"\n              required\n            />\n            <Box sx={{ display: \"flex\", alignItems: \"center\", gap: 2 }}>\n              <Typography variant=\"body2\">Color:</Typography>\n              <TextField\n                type=\"color\"\n                value={newListColor}\n                onChange={(e) => setNewListColor(e.target.value)}\n                sx={{\n                  width: 80,\n                  \"& input\": {\n                    height: 40,\n                    cursor: \"pointer\",\n                  },\n                }}\n                inputProps={{\n                  \"aria-label\": \"List color\",\n                }}\n              />\n              <Box\n                sx={{\n                  width: 40,\n                  height: 40,\n                  borderRadius: 1,\n                  backgroundColor: newListColor,\n                  border: \"1px solid\",\n                  borderColor: \"divider\",\n                }}\n                aria-label={`Selected color: ${newListColor}`}\n              />\n            </Box>\n          </Box>\n        </DialogContent>\n        <DialogActions>\n          <Button onClick={handleClose}>Cancel</Button>\n          <Button\n            onClick={handleSave}\n            variant=\"contained\"\n            disabled={!newListName.trim() || !newListData.trim()}\n          >\n            Save\n          </Button>\n        </DialogActions>\n      </Dialog>\n    </Box>\n  );\n}\n",
