    "import { useMemo } from \"react\";\nimport {\n  Box,\n  Typography,\n  Table,\n  TableBody,\n  TableCell,\n  TableContainer,\n  TableHead,\n  TableRow,\n  Paper,\n} from \"@mui/material\";\nimport { pinyin } from \"pinyin\";\n\ninterface HanziMapScreenProps {\n  text: string;\n}\n\nconst INITIALS = [\"∅\", \"b\", \"p\", \"m\", \"f\", \"d\", \"t\", \"n\", \"l\", \"g\", \"k\", \"h\", \"j\", \"q\", \"x\", \"z\", \"c\", \"s\", \"zh\", \"ch\", \"sh\", \"r\"];\nconst FINALS = [\"i\", \"a\", \"ai\", \"an\", \"ang\", \"ao\", \"e\", \"ei\", \"en\", \"eng\", \"er\", \"ia\", \"ian\", \"iang\", \"iao\", \"ie\", \"in\", \"ing\", \"iong\", \"iou\", \"o\", \"ong\", \"ou\", \"u\", \"ua\", \"uai\", \"uan\", \"uang\", \"uei\", \"uen\", \"ueng\", \"uo\", \"ü\", \"üan\", \"üe\", \"ün\"];\n\nfunction removeTones(pinyinStr: string): string {\n  return pinyinStr\n    .replace(/[āáǎà]/g, \"a\")\n    .replace(/[ēéěè]/g, \"e\")\n    .replace(/[īíǐì]/g, \"i\")\n    .replace(/[ōóǒò]/g, \"o\")\n    .replace(/[ūúǔù]/g, \"u\")\n    .replace(/[ǖǘǚǜ]/g, \"ü\");\n}\n\n// Map common pinyin variations to standard finals\nconst PINYIN_VARIATIONS: Record<string, string> = {\n  \"iu\": \"iou\",\n  \"ui\": \"uei\",\n  \"un\": \"uen\",\n};\n\nfunction normalizePinyin(pinyinStr: string): string {\n  let normalized = removeTones(pinyinStr.toLowerCase());\n  \n  // Handle variations\n  for (const [variant, standard] of Object.entries(PINYIN_VARIATIONS)) {\n    if (normalized.endsWith(variant)) {\n      normalized = normalized.slice(0, -variant.length) + standard;\n      break;\n    }\n  }\n  \n  return normalized;\n}\n\nfunction parsePinyinToSyllable(pinyinStr: string): { initial: string; final: string } | null {\n  const normalized = normalizePinyin(pinyinStr);\n  \n  // Sort initials by length (longest first) to match \"zh\", \"ch\", \"sh\" before single letters\n  const sortedInitials = [...INITIALS].sort((a, b) => b.length - a.length);\n  \n  for (const initial of sortedInitials) {\n    if (initial === \"∅\") continue;\n    \n    if (normalized.startsWith(initial)) {\n      const final = normalized.slice(initial.length);\n      if (FINALS.includes(final)) {\n        return { initial, final };\n      }\n    }\n  }\n  \n  // Check if it's a zero-initial syllable (just a final)\n  if (FINALS.includes(normalized)) {\n    return { initial: \"∅\", final: normalized };\n  }\n  \n  return null;\n}\n\nexport function HanziMapScreen({ text }: HanziMapScreenProps) {\n  const hanziMap = useMemo(() => {\n    const hanziRegex = /[\\u4e00-\\u9fff]/g;\n    const matches = text.match(hanziRegex);\n    if (!matches) return new Map<string, string[]>();\n    \n    const map = new Map<string, string[]>();\n    \n    matches.forEach((hanzi) => {\n      try {\n        const pinyinResult = pinyin(hanzi, {\n          style: pinyin.STYLE_TONE,\n          heteronym: false,\n        });\n        \n        if (pinyinResult && pinyinResult.length > 0 && pinyinResult[0].length > 0) {\n          const pinyinStr = pinyinResult[0][0];\n          const syllable = parsePinyinToSyllable(pinyinStr);\n          \n          if (syllable) {\n            const key = `${syllable.initial}-${syllable.final}`;\n            if (!map.has(key)) {\n              map.set(key, []);\n            }\n            const hanziList = map.get(key)!;\n            if (!hanziList.includes(hanzi)) {\n              hanziList.push(hanzi);\n            }\n          }\n        }\n      } catch (error) {\n        console.error(`Error converting hanzi ${hanzi} to pinyin:`, error);\n      }\n    });\n    \n    return map;\n  }, [text]);\n\n  const hanziSet = useMemo(() => {\n    const hanziRegex = /[\\u4e00-\\u9fff]/g;\n    const matches = text.match(hanziRegex);\n    return new Set(matches || []);\n  }, [text]);\n\n  const getSyllable = (initial: string, final: string): string => {\n    if (initial === \"∅\") {\n      return final;\n    }\n    return initial + final;\n  };\n\n  const getHanziForCell = (initial: string, final: string): string[] => {\n    const key = `${initial}-${final}`;\n    return hanziMap.get(key) || [];\n  };\n\n  return (\n    <Box sx={{ p: 3, height: \"100%\", overflow: \"auto\" }}>\n      <Typography variant=\"h5\" gutterBottom>\n        Hanzi Map\n      </Typography>\n      <Typography variant=\"body2\" sx={{ mb: 2, color: \"text.secondary\" }}>\n        {hanziSet.size > 0\n          ? `Found ${hanziSet.size} unique hanzi in the text`\n          : \"No hanzi found in the text. Enter text in the Input screen.\"}\n      </Typography>\n      <TableContainer component={Paper} sx={{ maxHeight: \"calc(100vh - 200px)\", overflow: \"auto\" }}>\n        <Table stickyHeader size=\"small\">\n          <TableHead>\n            <TableRow>\n              <TableCell\n                sx={{\n                  position: \"sticky\",\n                  left: 0,\n                  zIndex: 3,\n                  backgroundColor: \"background.paper\",\n                  borderRight: \"1px solid\",\n                  borderColor: \"divider\",\n                  minWidth: 60,\n                }}\n              >\n                Initial\\Final\n              </TableCell>\n              {FINALS.map((final) => (\n                <TableCell\n                  key={final}\n                  align=\"center\"\n                  sx={{\n                    minWidth: 50,\n                    fontSize: \"0.75rem\",\n                  }}\n                >\n                  {final}\n                </TableCell>\n              ))}\n            </TableRow>\n          </TableHead>\n          <TableBody>\n            {INITIALS.map((initial) => (\n              <TableRow key={initial}>\n                <TableCell\n                  sx={{\n                    position: \"sticky\",\n                    left: 0,\n                    zIndex: 2,\n                    backgroundColor: \"background.paper\",\n                    borderRight: \"1px solid\",\n                    borderColor: \"divider\",\n                    fontWeight: \"bold\",\n                  }}\n                >\n                  {initial}\n                </TableCell>\n                {FINALS.map((final) => {\n                  const hanziList = getHanziForCell(initial, final);\n                  const hasHanzi = hanziList.length > 0;\n                  return (\n                    <TableCell\n                      key={`${initial}-${final}`}\n                      align=\"center\"\n                      sx={{\n                        backgroundColor: hasHanzi ? \"action.selected\" : \"transparent\",\n                        fontSize: \"0.7rem\",\n                        minWidth: 50,\n                        padding: \"4px\",\n                      }}\n                    >\n                      {hasHanzi ? (\n                        <Box\n                          sx={{\n                            display: \"flex\",\n                            flexWrap: \"wrap\",\n                            gap: \"2px\",\n                            justifyContent: \"center\",\n                            fontSize: \"0.9rem\",\n                          }}\n                        >\n                          {hanziList.map((hanzi, idx) => (\n                            <Box key={idx} component=\"span\">\n                              {hanzi}\n                            </Box>\n                          ))}\n                        </Box>\n                      ) : (\n                        <Box sx={{ color: \"text.disabled\", fontSize: \"0.6rem\" }}>\n                          {getSyllable(initial, final)}\n                        </Box>\n                      )}\n                    </TableCell>\n                  );\n                })}\n              </TableRow>\n            ))}\n          </TableBody>\n        </Table>\n      </TableContainer>\n    </Box>\n  );\n}\n\n",
    "import { useMemo, useEffect, useState } from \"react\";\nimport { Box, Typography, Tooltip } from \"@mui/material\";\nimport { pinyin } from \"pinyin\";\nimport { HanziListStore } from \"../store/HanziListStore\";\nimport { PREDEFINED_LISTS } from \"../store/predefinedLists\";\nimport { HanziList } from \"../store/types/HanziList\";\n\ninterface ReaderScreenProps {\n  text: string;\n}\n\nfunction hexToRgb(hex: string): { r: number; g: number; b: number } | null {\n  const result = /^#?([a-f\\d]{2})([a-f\\d]{2})([a-f\\d]{2})$/i.exec(hex);\n  return result\n    ? {\n        r: parseInt(result[1], 16),\n        g: parseInt(result[2], 16),\n        b: parseInt(result[3], 16),\n      }\n    : null;\n}\n\nfunction rgbToHex(r: number, g: number, b: number): string {\n  return \"#\" + [r, g, b].map((x) => x.toString(16).padStart(2, \"0\")).join(\"\");\n}\n\nfunction mixColors(colors: string[]): string {\n  if (colors.length === 0) return \"#000000\";\n  if (colors.length === 1) return colors[0];\n\n  const rgbs = colors.map(hexToRgb).filter((rgb) => rgb !== null) as {\n    r: number;\n    g: number;\n    b: number;\n  }[];\n\n  if (rgbs.length === 0) return \"#000000\";\n\n  const avgR = Math.round(\n    rgbs.reduce((sum, rgb) => sum + rgb.r, 0) / rgbs.length\n  );\n  const avgG = Math.round(\n    rgbs.reduce((sum, rgb) => sum + rgb.g, 0) / rgbs.length\n  );\n  const avgB = Math.round(\n    rgbs.reduce((sum, rgb) => sum + rgb.b, 0) / rgbs.length\n  );\n\n  return rgbToHex(avgR, avgG, avgB);\n}\n\nexport function ReaderScreen({ text }: ReaderScreenProps) {\n  const store = useMemo(() => new HanziListStore(), []);\n  const [userLists, setUserLists] = useState<HanziList[]>([]);\n\n  useEffect(() => {\n    try {\n      const lists = store.load();\n      setUserLists(lists);\n    } catch (error) {\n      console.error(\"Failed to load lists:\", error);\n      setUserLists([]);\n    }\n  }, [store]);\n\n  const allLists = useMemo(() => {\n    return [...PREDEFINED_LISTS, ...userLists];\n  }, [userLists]);\n\n  const hanziToColors = useMemo(() => {\n    const map = new Map<string, string[]>();\n    allLists.forEach((list) => {\n      if (list.color) {\n        Array.from(list.data).forEach((hanzi) => {\n          if (!map.has(hanzi)) {\n            map.set(hanzi, []);\n          }\n          map.get(hanzi)!.push(list.color!);\n        });\n      }\n    });\n    return map;\n  }, [allLists]);\n\n  const hanziToListNames = useMemo(() => {\n    const map = new Map<string, string[]>();\n    allLists.forEach((list) => {\n      Array.from(list.data).forEach((hanzi) => {\n        if (!map.has(hanzi)) {\n          map.set(hanzi, []);\n        }\n        map.get(hanzi)!.push(list.name);\n      });\n    });\n    return map;\n  }, [allLists]);\n\n  const getPinyin = (hanzi: string): string => {\n    try {\n      const pinyinResult = pinyin(hanzi, {\n        style: pinyin.STYLE_TONE,\n        heteronym: false,\n      });\n      if (pinyinResult && pinyinResult.length > 0 && pinyinResult[0].length > 0) {\n        return pinyinResult[0][0];\n      }\n    } catch (error) {\n      console.error(`Error converting hanzi ${hanzi} to pinyin:`, error);\n    }\n    return \"\";\n  };\n\n  const getColor = (hanzi: string): string | null => {\n    const colors = hanziToColors.get(hanzi);\n    if (!colors || colors.length === 0) return null;\n    return mixColors(colors);\n  };\n\n  const getListNames = (hanzi: string): string[] => {\n    return hanziToListNames.get(hanzi) || [];\n  };\n\n  return (\n    <Box\n      sx={{\n        p: 3,\n        height: \"100%\",\n        overflow: \"auto\",\n        display: \"flex\",\n        flexDirection: \"column\",\n      }}\n    >\n      <Typography variant=\"h5\" gutterBottom>\n        Reader\n      </Typography>\n      <Box\n        sx={{\n          mt: 2,\n          display: \"flex\",\n          flexWrap: \"wrap\",\n          gap: \"8px\",\n          lineHeight: 1.2,\n          fontSize: \"36pt\",\n          fontFamily: \"serif\",\n        }}\n      >\n        {Array.from(text).map((char, index) => {\n          const isHanzi = /[\\u4e00-\\u9fff]/.test(char);\n          const color = isHanzi ? getColor(char) : null;\n          const pinyinText = isHanzi ? getPinyin(char) : \"\";\n          const listNames = isHanzi ? getListNames(char) : [];\n\n          if (isHanzi) {\n            const tooltipTitle =\n              listNames.length > 0\n                ? `Lists: ${listNames.join(\", \")}`\n                : \"Not in any list\";\n\n            return (\n              <Tooltip key={index} title={tooltipTitle} arrow>\n                <Box\n                  sx={{\n                    display: \"inline-flex\",\n                    flexDirection: \"column\",\n                    alignItems: \"center\",\n                    justifyContent: \"flex-start\",\n                    verticalAlign: \"top\",\n                    position: \"relative\",\n                    cursor: \"help\",\n                  }}\n                >\n                  <Typography\n                    variant=\"caption\"\n                    sx={{\n                      fontSize: \"0.35em\",\n                      lineHeight: 1,\n                      mb: \"0.1em\",\n                      color: \"text.secondary\",\n                      fontFamily: \"sans-serif\",\n                    }}\n                  >\n                    {pinyinText}\n                  </Typography>\n                  <Box\n                    component=\"span\"\n                    sx={{\n                      color: color || \"inherit\",\n                      fontSize: \"1em\",\n                      lineHeight: 1,\n                    }}\n                  >\n                    {char}\n                  </Box>\n                </Box>\n              </Tooltip>\n            );\n          } else {\n            return (\n              <Box\n                key={index}\n                component=\"span\"\n                sx={{\n                  whiteSpace: char === \"\\n\" ? \"pre\" : \"normal\",\n                  display: char === \"\\n\" ? \"block\" : \"inline\",\n                  width: char === \"\\n\" ? \"100%\" : \"auto\",\n                }}\n              >\n                {char === \" \" ? \"\\u00A0\" : char}\n              </Box>\n            );\n          }\n        })}\n      </Box>\n    </Box>\n  );\n}\n\n",
    "import { Paper, BottomNavigation, BottomNavigationAction } from \"@mui/material\";\nimport { TextFields, Assessment, Settings, Map, MenuBook } from \"@mui/icons-material\";\n\nexport type Screen = \"input\" | \"report\" | \"configuration\" | \"map\" | \"reader\";\n\ninterface BottomNavigationPanelProps {\n  currentScreen: Screen;\n  onScreenChange: (screen: Screen) => void;\n}\n\nexport function BottomNavigationPanel({\n  currentScreen,\n  onScreenChange,\n}: BottomNavigationPanelProps) {\n  return (\n    <Paper\n      sx={{ position: \"fixed\", bottom: 0, left: 0, right: 0, zIndex: 1000 }}\n      elevation={3}\n    >\n      <BottomNavigation\n        value={currentScreen}\n        onChange={(_, newValue) => onScreenChange(newValue)}\n        showLabels\n      >\n        <BottomNavigationAction\n          label=\"Input\"\n          value=\"input\"\n          icon={<TextFields />}\n        />\n        <BottomNavigationAction\n          label=\"Report\"\n          value=\"report\"\n          icon={<Assessment />}\n        />\n        <BottomNavigationAction\n          label=\"Config\"\n          value=\"configuration\"\n          icon={<Settings />}\n        />\n        <BottomNavigationAction\n          label=\"Map\"\n          value=\"map\"\n          icon={<Map />}\n        />\n        <BottomNavigationAction\n          label=\"Reader\"\n          value=\"reader\"\n          icon={<MenuBook />}\n        />\n      </BottomNavigation>\n    </Paper>\n  );\n}\n\n"
  ],
